import{g as a,ae as t,r,B as o}from"./chunks/framework.DRW4YgdI.js";const f=JSON.parse('{"title":"v1 Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"docs/changelog/v1.md","filePath":"docs/changelog/v1.md","lastUpdated":1793353150000}'),l={name:"docs/changelog/v1.md"};function i(n,e,s,h,p,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="v1-changelog" tabindex="-1">v1 Changelog <a class="header-anchor" href="#v1-changelog" aria-label="Permalink to “v1 Changelog”">​</a></h1><p>Every frappe-ui 1.x release, newest first. Each entry names its kind in parentheses (fix, additive or deprecation) and links to its pull request. To upgrade from v0, see <a href="/pr-preview/pr-1333/docs/changelog/v0-to-v1">Changes from v0 to v1</a> and the <a href="/pr-preview/pr-1333/docs/migration">migration guide</a>.</p><h2 id="_1-1-1" tabindex="-1">1.1.1 <a class="header-anchor" href="#_1-1-1" aria-label="Permalink to “1.1.1”">​</a></h2><h3 id="patch-changes" tabindex="-1">Patch Changes <a class="header-anchor" href="#patch-changes" aria-label="Permalink to “Patch Changes”">​</a></h3><ul><li>Vite: <code>frappeTypes</code> finds doctype files in one pass over the app and skips <code>node_modules</code> and dot folders. Type generation on dev start no longer takes minutes in apps with a large <code>node_modules</code>. <a href="https://github.com/frappe/frappe-ui/pull/1331" target="_blank" rel="noreferrer">#1331</a></li></ul><h2 id="_1-1-0" tabindex="-1">1.1.0 <a class="header-anchor" href="#_1-1-0" aria-label="Permalink to “1.1.0”">​</a></h2><h3 id="minor-changes" tabindex="-1">Minor Changes <a class="header-anchor" href="#minor-changes" aria-label="Permalink to “Minor Changes”">​</a></h3><ul><li>Charts: <code>DonutChart</code> and <code>PercentageBarChart</code> take <code>order: &#39;rows&#39;</code>, which draws the slices in the order the rows arrive instead of biggest first, for ordered categories such as ageing buckets. <a href="https://github.com/frappe/frappe-ui/pull/1307" target="_blank" rel="noreferrer">#1307</a></li><li>Charts: new <code>CalendarHeatmapChart</code> colors one cell per day, laid out by week and weekday, in bands of twelve months past a year. <a href="https://github.com/frappe/frappe-ui/pull/1307" target="_blank" rel="noreferrer">#1307</a></li><li>Charts: <code>ChartContainer</code> takes <code>centered</code>, which centres a plot as tall as its content together with its legend in the height to spare; <code>PercentageBarChart</code> uses it, so its legend stays under the bar. <a href="https://github.com/frappe/frappe-ui/pull/1307" target="_blank" rel="noreferrer">#1307</a></li><li>Charts: the legend now takes one row at most; when the series do not fit, it shows the largest ones and a &quot;+N more&quot; button that lists every series, largest first, with a search field past 15. <a href="https://github.com/frappe/frappe-ui/pull/1294" target="_blank" rel="noreferrer">#1294</a></li><li>Charts: colors given as a CSS variable, such as <code>var(--brand)</code> in <code>palette</code>, <code>seriesConfig</code> or a reference line, now resolve against the chart&#39;s element and follow theme changes. <a href="https://github.com/frappe/frappe-ui/pull/1307" target="_blank" rel="noreferrer">#1307</a></li><li>Charts: a value axis whose values are all whole numbers now ticks in whole numbers, so a small count no longer reads 0.5 or 1.5; the new <code>integer</code> option on <code>yAxis</code>, <code>y2Axis</code> and a scatter&#39;s axes turns it on or off. <a href="https://github.com/frappe/frappe-ui/pull/1307" target="_blank" rel="noreferrer">#1307</a></li><li>Charts: <code>DonutChart</code> takes <code>colors</code>, a map from category value to color, so a slice such as &quot;Overdue&quot; keeps its color whatever its size. <a href="https://github.com/frappe/frappe-ui/pull/1307" target="_blank" rel="noreferrer">#1307</a></li><li>Duration: the new <code>largestUnit</code> and <code>smallestUnit</code> props show days (<code>1d 2h 3m 4s</code>) or round to the minute, and the input reads <code>1d</code> and <code>2 days</code>. A minute field reads a bare <code>15</code> as 15 minutes and <code>1:30</code> as 1h 30m. <code>formatDuration</code> and <code>parseDuration</code> take the same units as an optional last argument, and the <code>DurationUnits</code> type is exported. <a href="https://github.com/frappe/frappe-ui/pull/1320" target="_blank" rel="noreferrer">#1320</a></li><li>MultiSelect: the new <code>highlight</code> event reports the highlighted option, or <code>null</code> once the popover closes. <a href="https://github.com/frappe/frappe-ui/pull/1298" target="_blank" rel="noreferrer">#1298</a></li><li>NumberCard: <code>progress</code> draws a bar for how far the reading has come towards a whole. <a href="https://github.com/frappe/frappe-ui/pull/1309" target="_blank" rel="noreferrer">#1309</a></li><li>Charts: new <code>PercentageBarChart</code> draws a breakdown as one bar, from the same rows and props as <code>DonutChart</code>. <a href="https://github.com/frappe/frappe-ui/pull/1307" target="_blank" rel="noreferrer">#1307</a></li><li>Charts: a reference line now stretches its value axis, so a goal above the data stays in view instead of not being drawn. <a href="https://github.com/frappe/frappe-ui/pull/1307" target="_blank" rel="noreferrer">#1307</a></li><li>Stepper: the new <code>Stepper</code> component shows progress through ordered steps, with sub-steps, skipped steps, and a running or failed current step. It ships from <code>frappe-ui/experimental</code> while its API is refined. <a href="https://github.com/frappe/frappe-ui/pull/1276" target="_blank" rel="noreferrer">#1276</a></li><li>Charts: <code>useChart</code> also returns the measured plot <code>height</code>. <a href="https://github.com/frappe/frappe-ui/pull/1307" target="_blank" rel="noreferrer">#1307</a></li></ul><h3 id="patch-changes-1" tabindex="-1">Patch Changes <a class="header-anchor" href="#patch-changes-1" aria-label="Permalink to “Patch Changes”">​</a></h3><ul><li>Avatar: the gap around the <code>#indicator</code> content is now cut out of the avatar, so it shows the surface behind the avatar (a hovered row, a popover, a dialog) instead of the page color. <a href="https://github.com/frappe/frappe-ui/pull/1311" target="_blank" rel="noreferrer">#1311</a></li><li>Charts: a <code>DonutChart</code> or <code>PercentageBarChart</code> with one slice now names it and its share in the legend. <a href="https://github.com/frappe/frappe-ui/pull/1307" target="_blank" rel="noreferrer">#1307</a></li><li>Charts: series named by a <code>splitBy</code> value and axis titles now print as given, without capitalizing. <a href="https://github.com/frappe/frappe-ui/pull/1293" target="_blank" rel="noreferrer">#1293</a></li><li>Charts: a value axis raised a tick to fit a label keeps its tick step, so the new end lands on a tick. <a href="https://github.com/frappe/frappe-ui/pull/1307" target="_blank" rel="noreferrer">#1307</a></li><li>Charts: a category axis too crowded to tilt every label now lays its labels flat and labels every few categories, keeping the first and the last, instead of tilting them and dropping the ones that collide. <a href="https://github.com/frappe/frappe-ui/pull/1307" target="_blank" rel="noreferrer">#1307</a></li><li>Charts: a category label printed by <code>xAxis.format</code> is now truncated in the middle when it is too long, like an unformatted label, instead of losing its end. <a href="https://github.com/frappe/frappe-ui/pull/1307" target="_blank" rel="noreferrer">#1307</a></li><li>Vite plugin: <code>codeLanguages</code> now works on Vite 8, where the dev server&#39;s dependency scan failed with <code>Not implemented</code>. <a href="https://github.com/frappe/frappe-ui/pull/1301" target="_blank" rel="noreferrer">#1301</a></li><li>Combobox: a disabled input-mode combobox now draws its value in the muted disabled ink, as Select does. <a href="https://github.com/frappe/frappe-ui/pull/1318" target="_blank" rel="noreferrer">#1318</a></li><li>Combobox: in <code>trigger=&quot;button&quot;</code> mode, a value that is not in the loaded options shows as text instead of the placeholder. An empty string value with no matching option still shows the placeholder. <a href="https://github.com/frappe/frappe-ui/pull/1209" target="_blank" rel="noreferrer">#1209</a></li><li>Dialog: <code>dialog.prompt</code> now focuses its first text or textarea field when it opens, and Enter in a single-line field submits it. <a href="https://github.com/frappe/frappe-ui/pull/1275" target="_blank" rel="noreferrer">#1275</a></li><li>Charts: a donut whose only non-zero slice is the whole draws a closed ring, and zero slices take no gap on the ring while staying in the legend. <a href="https://github.com/frappe/frappe-ui/pull/1307" target="_blank" rel="noreferrer">#1307</a></li><li>Charts: a breakdown&#39;s shares add up to 100% in <code>DonutChart</code>&#39;s legend, tooltip and labels, and <code>DonutSliceEvent.percent</code> is now that rounded whole-number share. <a href="https://github.com/frappe/frappe-ui/pull/1307" target="_blank" rel="noreferrer">#1307</a></li><li>Editor: resizing an image, video or embed now snaps to 25%, 50%, 75% and full width, to the media&#39;s original size, and to the width of other media in the document, with a guide line and a width label while you drag; hold Alt to resize freely. <a href="https://github.com/frappe/frappe-ui/pull/1316" target="_blank" rel="noreferrer">#1316</a></li><li>Editor: content set from outside through <code>v-model</code> no longer adds an undo step, so undo cannot wipe a document that loaded after the editor mounted. <a href="https://github.com/frappe/frappe-ui/pull/1299" target="_blank" rel="noreferrer">#1299</a></li><li>useCall, useIsolatedCall: a <code>GET</code> request now sends object and array params as JSON in the query string, so Frappe can parse them. <a href="https://github.com/frappe/frappe-ui/pull/1233" target="_blank" rel="noreferrer">#1233</a></li><li>HeatmapChart: when no value is negative, the color scale now starts at 0 instead of at the smallest value, so the smallest cell no longer draws as pale as an empty one; set <code>min</code> for the old scale. <a href="https://github.com/frappe/frappe-ui/pull/1307" target="_blank" rel="noreferrer">#1307</a></li><li>Dropdown, ContextMenu: rows in a group now have a 1px gap between them, so a highlighted row next to a selected row no longer looks like one block. <a href="https://github.com/frappe/frappe-ui/pull/1274" target="_blank" rel="noreferrer">#1274</a></li><li>Dropdown, ContextMenu: a menu taller than the space on screen now scrolls instead of running off the edge. <a href="https://github.com/frappe/frappe-ui/pull/1300" target="_blank" rel="noreferrer">#1300</a></li><li>MultiEmailInput: chips now use the design system&#39;s tag size, with a 20px height, a 12px avatar and a 12px close icon. The suggestion list no longer opens empty: it stays closed on focus when there is nothing to suggest, and while a typed address matches nothing, unless <code>emptyText</code> or the <code>empty</code> slot is set. A click reopens it after Escape. <a href="https://github.com/frappe/frappe-ui/pull/1306" target="_blank" rel="noreferrer">#1306</a></li><li>MultiSelect: a checked row is no longer filled grey; its checkbox shows the state. <a href="https://github.com/frappe/frappe-ui/pull/1298" target="_blank" rel="noreferrer">#1298</a></li><li>MultiSelect: attributes such as <code>aria-label</code> reach the trigger, as on Select, and the list takes its name from <code>label</code> or <code>aria-label</code>. <a href="https://github.com/frappe/frappe-ui/pull/1298" target="_blank" rel="noreferrer">#1298</a></li><li>NumberCard: a card with no title, <code>title-suffix</code> or <code>actions</code> no longer leaves an empty row above the number. <a href="https://github.com/frappe/frappe-ui/pull/1307" target="_blank" rel="noreferrer">#1307</a></li><li>NumberCard: a delta that prints as zero, such as <code>0.04</code> shown as &quot;0%&quot;, now reads as flat: no arrow, neutral tone. <a href="https://github.com/frappe/frappe-ui/pull/1307" target="_blank" rel="noreferrer">#1307</a></li><li>Stepper: an app that scans frappe-ui&#39;s Tailwind content globs now gets the classes <code>Stepper</code> from <code>frappe-ui/experimental</code> draws with, so it no longer renders unstyled. <a href="https://github.com/frappe/frappe-ui/pull/1308" target="_blank" rel="noreferrer">#1308</a></li><li>Switch: disabled switches use distinct backgrounds for on and off states. <a href="https://github.com/frappe/frappe-ui/pull/1292" target="_blank" rel="noreferrer">#1292</a></li><li>Charts: <code>xAxis.format</code> on a time axis prints the date in the tooltip and no longer flattens the levelled tick labels. <a href="https://github.com/frappe/frappe-ui/pull/1307" target="_blank" rel="noreferrer">#1307</a></li><li>useList, useCall: a request that a newer request replaces, such as the first of two quick <code>reload()</code> calls, no longer sets <code>error</code> or calls <code>onError</code>. <a href="https://github.com/frappe/frappe-ui/pull/1312" target="_blank" rel="noreferrer">#1312</a></li></ul><h2 id="_1-0-2" tabindex="-1">1.0.2 <a class="header-anchor" href="#_1-0-2" aria-label="Permalink to “1.0.2”">​</a></h2><h3 id="patch-changes-2" tabindex="-1">Patch Changes <a class="header-anchor" href="#patch-changes-2" aria-label="Permalink to “Patch Changes”">​</a></h3><ul><li>Editor: the suggestion menus (@mention, /, #, 😃 can now be clicked inside a Dialog without closing it (fix). <a href="https://github.com/frappe/frappe-ui/pull/1288" target="_blank" rel="noreferrer">#1288</a></li><li>Editor: @mention results now list an exact name match first, then names that start with the typed text, then names with a word that starts with it (fix). <a href="https://github.com/frappe/frappe-ui/pull/1288" target="_blank" rel="noreferrer">#1288</a></li><li>MobileShell: in an installed iOS 26 app, the tab bar now reaches the bottom edge and clears the home indicator; <code>frappe-ui/style.css</code> now gives every installed app with a translucent status bar a page at least as tall as the screen, which is what restores the full-screen viewport (fix). <a href="https://github.com/frappe/frappe-ui/pull/1289" target="_blank" rel="noreferrer">#1289</a></li><li>Combobox, MultiSelect: search results now list exact matches first, then labels that start with the typed text, then labels with a word that starts with it (fix). <a href="https://github.com/frappe/frappe-ui/pull/1290" target="_blank" rel="noreferrer">#1290</a></li><li>Vite plugin: an app linked into a bench&#39;s <code>apps/</code> from another folder now builds and runs in dev; tools such as Pilot set <code>FRAPPE_BENCH_PATH</code> to the bench (fix). <a href="https://github.com/frappe/frappe-ui/pull/1283" target="_blank" rel="noreferrer">#1283</a></li></ul><h2 id="_1-0-1" tabindex="-1">1.0.1 <a class="header-anchor" href="#_1-0-1" aria-label="Permalink to “1.0.1”">​</a></h2><h3 id="patch-changes-3" tabindex="-1">Patch Changes <a class="header-anchor" href="#patch-changes-3" aria-label="Permalink to “Patch Changes”">​</a></h3><ul><li>Charts: a category axis label that is shortened in the middle now keeps its ending, and no longer gets a second ellipsis at the end (fix). <a href="https://github.com/frappe/frappe-ui/pull/1279" target="_blank" rel="noreferrer">#1279</a></li><li>Checkbox: a checked or indeterminate checkbox now lightens on hover and press, and checkboxes no longer show a shadow on hover (fix). <a href="https://github.com/frappe/frappe-ui/pull/1186" target="_blank" rel="noreferrer">#1186</a></li><li>Editor: images and videos without a size get one only after the person&#39;s own edit, not when a document opens or a collaborator edits it, and one Ctrl+Z now undoes the person&#39;s edit (fix). <a href="https://github.com/frappe/frappe-ui/pull/1266" target="_blank" rel="noreferrer">#1266</a></li><li>PageHeaderMobile: the <code>#prefix</code> and <code>#suffix</code> slots now follow the text direction, so in right-to-left pages the back button sits on the right (fix). <a href="https://github.com/frappe/frappe-ui/pull/1230" target="_blank" rel="noreferrer">#1230</a></li><li>Progress: a bar without a <code>label</code> now has the accessible name &quot;Progress&quot; instead of its percentage, so screen readers do not read the value twice (fix). <a href="https://github.com/frappe/frappe-ui/pull/1113" target="_blank" rel="noreferrer">#1113</a></li><li>SidebarRailItem: a <code>subtle</code> item paints no fill behind an image, so a rounded logo shows no gray rim at its corners (fix). <a href="https://github.com/frappe/frappe-ui/pull/1272" target="_blank" rel="noreferrer">#1272</a></li><li>Editor: dragging a link or selected text out of a read-only editor now carries the browser&#39;s URL or text, as it does from plain HTML (fix). <a href="https://github.com/frappe/frappe-ui/pull/1104" target="_blank" rel="noreferrer">#1104</a></li><li>Realtime: updates keep arriving after a reconnect and on a new socket (fix). <a href="https://github.com/frappe/frappe-ui/pull/1105" target="_blank" rel="noreferrer">#1105</a></li><li>Editor: the mention, emoji, tag and slash-command menus stay next to the caret when the page or the editor&#39;s scroll container scrolls or the window resizes, and never show a position meant for an older list (fix). <a href="https://github.com/frappe/frappe-ui/pull/1161" target="_blank" rel="noreferrer">#1161</a></li></ul>',16)])])}const u=a(l,[["render",i]]);export{f as __pageData,u as default};
